// src/components/HowToSignUp.js
import React, { useState } from 'react';
import './HowToSignUp.css';  // External CSS for better control and styling

const HowToSignUp = () => {
  const [selectedType, setSelectedType] = useState(null);
  const [gearChecklist, setGearChecklist] = useState({
    swim: false,
    bike: false,
    run: false,
    nutrition: false
  });
  const [quizScore, setQuizScore] = useState(0);
  const [progress, setProgress] = useState(0);

  const handleTypeSelect = (type) => {
    setSelectedType(type);
    setProgress(progress + 25);  // Increase progress on type selection
  };

  const handleChecklistChange = (item) => {
    setGearChecklist({ ...gearChecklist, [item]: !gearChecklist[item] });
    if (!gearChecklist[item]) setProgress(progress + 10);  // Increment progress on checklist completion
  };

  const handleQuizAnswer = (isCorrect) => {
    if (isCorrect) setQuizScore(quizScore + 1);
    setProgress(progress + 15);  // Increment progress with each quiz answer
  };

  const renderRaceTips = () => {
    switch (selectedType) {
      case "Sprint":
        return "Sprint Triathlon: Focus on shorter training sessions with balanced practice across stages.";
      case "Olympic":
        return "Olympic Triathlon: Train for endurance with a moderate weekly routine.";
      case "Half Ironman":
        return "Half Ironman: Requires strong endurance. Practice long-distance and pacing.";
      case "Ironman":
        return "Ironman: Elite training. Consult a coach, optimize for endurance and recovery.";
      default:
        return "Choose a race type to see specific tips.";
    }
  };

  return (
    <div className="signup-container">
      <h1 className="signup-title">How to Sign Up for a Triathlon</h1>

      <div className="progress-tracker">
        <div className="progress-circle">
          <div className="progress" style={{ strokeDashoffset: `calc(100 - ${progress})` }}></div>
          <div className="progress-text">{progress}%</div>
        </div>
        <p>Complete each step to reach 100% readiness!</p>
      </div>

      <h2>1. Choose Your Triathlon Type</h2>
      <p>Select a race type for customized tips and requirements:</p>
      <div className="race-selector">
        {["Sprint", "Olympic", "Half Ironman", "Ironman"].map((type) => (
          <div
            key={type}
            className={`race-card ${selectedType === type ? 'selected' : ''}`}
            onClick={() => handleTypeSelect(type)}
          >
            <h3>{type}</h3>
            {selectedType === type && (
              <p className="race-details">{renderRaceTips()}</p>
            )}
          </div>
        ))}
      </div>

      <h2>2. Register for the Event</h2>
      <p>
        Register on <a href="https://www.active.com" target="_blank" rel="noopener noreferrer">Active.com</a> or <a href="https://www.ironman.com" target="_blank" rel="noopener noreferrer">Ironman</a>.
        <span> Register early, as spots fill up quickly!</span>
      </p>

      <h2>3. Gear Checklist</h2>
      <p>Check off each item as you prepare:</p>
      <ul className="checklist">
        {Object.keys(gearChecklist).map((item) => (
          <li key={item} onClick={() => handleChecklistChange(item)}>
            <input
              type="checkbox"
              checked={gearChecklist[item]}
              onChange={() => handleChecklistChange(item)}
            />
            <span className={`checklist-item ${gearChecklist[item] ? "checked" : ""}`}>
              {item.charAt(0).toUpperCase() + item.slice(1)} Gear
            </span>
          </li>
        ))}
      </ul>

      <h2>4. Preparing for Race Day</h2>
      <p>Plan for each stage and ensure your gear and nutrition are ready:</p>
      <div className="training-panel">
        {selectedType ? (
          <>
            <h3>{selectedType} Training Plan</h3>
            <ul>
              {selectedType === "Sprint" && <li>8-week plan with focus on consistency and balanced training.</li>}
              {selectedType === "Olympic" && <li>12-week endurance plan with moderate swim, bike, and run.</li>}
              {selectedType === "Half Ironman" && <li>16-week plan with long-distance endurance sessions.</li>}
              {selectedType === "Ironman" && <li>24-week dedicated training with personalized coaching suggested.</li>}
            </ul>
          </>
        ) : (
          <p>Select a race type to see a suggested training plan.</p>
        )}
      </div>

      <h2>5. FAQs</h2>
      <div className="faq-section">
        <details>
          <summary>What should I wear during a triathlon?</summary>
          <p>A tri-suit is ideal for quick transitions between stages.</p>
        </details>
        <details>
          <summary>Can beginners attempt an Ironman?</summary>
          <p>Yes, but extensive training is needed. Consult a coach for the best results.</p>
        </details>
        <details>
          <summary>How should I fuel during the race?</summary>
          <p>Refuel every 45-60 minutes with electrolytes and snacks.</p>
        </details>
      </div>

      <h2>6. Quiz Yourself</h2>
      <p>Test your triathlon knowledge!</p>
      <div className="quiz-section">
        <p>1. Which triathlon type is ideal for beginners?</p>
        {["Sprint", "Olympic", "Half Ironman", "Ironman"].map((type) => (
          <button
            key={type}
            onClick={() => handleQuizAnswer(type === "Sprint")}
          >
            {type}
          </button>
        ))}
        <p>Your score: {quizScore}/1</p>
      </div>
    </div>
  );
};

export default HowToSignUp;
